{@link https://en.wikipedia.org/wiki/Cache_replacement_policies#LRU | Least-recently-used cache}

Automatically removes entries above the max size based on when they were
last accessed with `get` or `set`.

Basic usage
```ts
import { LruCache } from "@ende/cache";
import { assert, assertEquals } from "@ende/assert";

const MAX_SIZE = 3;
const cache = new LruCache<string, number>(MAX_SIZE);

cache.set("a", 1);
cache.set("b", 2);
cache.set("c", 3);
cache.set("d", 4);

// most recent values are stored up to `MAX_SIZE`
assertEquals(cache.get("b"), 2);
assertEquals(cache.get("c"), 3);
assertEquals(cache.get("d"), 4);

// less recent values are removed
assert(!cache.has("a"));
```

Adding an onEject callback
```ts
import { LruCache } from "@ende/cache";
import { assertEquals } from "@ende/assert";

const ejected: [string, number, string][] = [];
const cache = new LruCache<string, number>(2, {
  onEject: (key, value, reason) => ejected.push([key, value, reason]),
});

cache.set("a", 1);
cache.set("b", 2);
cache.set("c", 3);

assertEquals(ejected, [["a", 1, "evicted"]]);
```

Max size
```ts
import { LruCache } from "@ende/cache";
import { assertEquals } from "@ende/assert";

const cache = new LruCache<string, number>(100);
assertEquals(cache.maxSize, 100);
```

Checking for the existence of a key
```ts
import { LruCache } from "@ende/cache";
import { assert } from "@ende/assert";

const cache = new LruCache<string, number>(100);

cache.set("a", 1);
assert(cache.has("a"));
```

Getting a value from the cache
```ts
import { LruCache } from "@ende/cache";
import { assertEquals } from "@ende/assert";

const cache = new LruCache<string, number>(100);

cache.set("a", 1);
assertEquals(cache.get("a"), 1);
```

Peeking at a value without promoting it
```ts
import { LruCache } from "@ende/cache";
import { assertEquals } from "@ende/assert";

const cache = new LruCache<string, number>(3);
cache.set("a", 1);
cache.set("b", 2);
cache.set("c", 3);

// peek does not promote "a"
assertEquals(cache.peek("a"), 1);

// "a" is still the least recently used and gets evicted
cache.set("d", 4);
assertEquals(cache.peek("a"), undefined);
```

Setting a value in the cache
```ts no-assert
import { LruCache } from "@ende/cache";

const cache = new LruCache<string, number>(100);
cache.set("a", 1);
```

Deleting a key from the cache
```ts
import { LruCache } from "@ende/cache";
import { assertEquals } from "@ende/assert/equals";

const cache = new LruCache<string, number>(1);

cache.set("a", 1);
cache.delete("a");
assertEquals(cache.has("a"), false);
```

Usage
```ts
import { LruCache } from "@ende/cache";
import { assertEquals } from "@ende/assert/equals";

const cache = new LruCache<string, number>(100);

cache.set("a", 1);
cache.set("b", 2);
cache.clear();
assertEquals(cache.size, 0);
```

```ts
import { memoize } from "@ende/cache";
import { assertEquals } from "@ende/assert";

const fn = memoize(({ value }: { cacheKey: number; value: number }) => {
  return value;
}, { getKey: ({ cacheKey }) => cacheKey });

assertEquals(fn({ cacheKey: 1, value: 2 }), 2);
assertEquals(fn({ cacheKey: 1, value: 99 }), 2);
assertEquals(fn({ cacheKey: 2, value: 99 }), 99);
```

Basic usage
```ts
import { memoize } from "@ende/cache";
import { assertEquals } from "@ende/assert";

// fibonacci function, which is very slow for n > ~30 if not memoized
const fib = memoize((n: bigint): bigint => {
  return n <= 2n ? 1n : fib(n - 1n) + fib(n - 2n);
});

assertEquals(fib(100n), 354224848179261915075n);
```

> [!NOTE]
> * By default, memoization is on the basis of all arguments passed to the
>   function, with equality determined by reference. This means that, for
>   example, passing a memoized function as `arr.map(func)` will not use the
>   cached results, as the index is implicitly passed as an argument. To
>   avoid this, you can pass a custom `getKey` option or use the memoized
>   function inside an anonymous callback like `arr.map((x) => func(x))`.

Usage
```ts
import { TtlCache } from "@ende/cache/ttl-cache";
import { assertEquals } from "@ende/assert/equals";
import { delay } from "@ende/async/delay";

const cache = new TtlCache<string, number>(1000);

cache.set("a", 1);
assertEquals(cache.size, 1);
await delay(2000);
assertEquals(cache.size, 0);
```

Sliding expiration
```ts
import { TtlCache } from "@ende/cache/ttl-cache";
import { assertEquals } from "@ende/assert/equals";
import { FakeTime } from "@ende/testing/time";

using time = new FakeTime(0);
const cache = new TtlCache<string, number>(100, {
  slidingExpiration: true,
});

cache.set("a", 1);
time.now = 80;
assertEquals(cache.get("a"), 1); // resets TTL
time.now = 160;
assertEquals(cache.get("a"), 1); // still alive, TTL was reset at t=80
time.now = 260;
assertEquals(cache.get("a"), undefined); // expired
```

